const assert=require('node:assert/strict');
const path=require('node:path');
const output=process.env.KEEP_COMPILED_DIR;
if(!output)throw new Error('Use scripts/check-keep-b3.cjs');
const get=p=>require(path.join(output,p));
const {buildKeepDiscoveryIndex,queryExistingSavedView,queryKeepDiscovery}=get('pkm/integration/keepDiscoveryModel.js');
const {buildProjectContext,buildKeepPlanningDays,reminderLocalDate,keepLocalDate,prepareKeepTaskReschedule}=get('pkm/integration/keepProjectContext.js');
const {savedViewsManager}=get('pkm/personalization/savedViewsManager.js');
const {makeOwnerRef}=get('pkm/integration/ownerResourceRefs.js');
const {buildVaultIndex}=get('pkm/vaultIndex.js');
const {configExportImportManager}=get('pkm/personalization/configExportImport.js');
let total=0;const check=(name,fn)=>{fn();total++;console.log(`PASS ${total} ${name}`)};
const note=(id,patch={})=>({id,title:id,content:'',type:'text',checklist:[],color:'default',tags:[],folderId:null,pinned:false,isFavorite:false,archived:false,trashed:false,isLocked:false,createdAt:'2026-10-10T08:00:00Z',updatedAt:'2026-10-16T08:00:00Z',reminderDate:null,images:[],...patch});
const projectNote=note('p',{title:'Analysis III seminar',content:'---\ntype: project\nstatus: active\n---\n## Tasks\n- [ ] Prepare presentation @due(2026-10-20) ^slides\n- [x] Review literature ^done',tags:['university'],reminderDate:'2026-10-19T08:00:00Z'});
const materialNote=note('r',{title:'Spectral theorem notes',content:'[[Analysis III seminar]]\n- [ ] Study proof @due(2026-10-18) ^proof',tags:['university'],linkedNoteIds:['p']});
const unlinked=note('u',{title:'Other university course',content:'- [ ] Different assignment @due(2026-10-19) ^unrelated',tags:['university']});
const locked=note('s',{title:'Private research',isLocked:true,content:'- [ ] Top secret @due(2026-10-17) ^private',linkedNoteIds:['p']});
const trashed=note('d',{title:'Discarded resource',trashed:true,content:'- [ ] Trash ^trash',linkedNoteIds:['p']});
const areaNote=note('a',{title:'University',content:'---\ntype: area\n---'});
const goalNote=note('g',{title:'Graduate',content:'---\ntype: goal\n---'});
const notes=[projectNote,materialNote,unlinked,locked,trashed,areaNote,goalNote];
const project={id:'p',noteId:'p',title:'Analysis III seminar',status:'active',goalIds:['g'],areaId:'a',areaTitle:'University',due:'2026-10-22',progressPercent:50,progressText:'1 of 2 tasks (50%)',blockedByIds:[],openTasksCount:1,completedTasksCount:1,totalTasksCount:2,nextActionTask:{text:'Prepare presentation',line:5},updatedAt:projectNote.updatedAt};
const goals=[{id:'g',noteId:'g',title:'Graduate',status:'active',supportingProjectIds:['p']}];
const areas=[{id:'a',noteId:'a',title:'University',status:'active',projectIds:['p'],goalIds:['g']}];
const projects=[project];
const index=buildKeepDiscoveryIndex(notes,projects,goals,areas);
const graph=buildVaultIndex(notes.filter(n=>!n.trashed&&!n.isLocked));
const make=(extra={},links=[])=>buildProjectContext('p',index,[{...project,...extra}],goals,areas,links,graph,'2026-10-16');
const projectContext=make();
check('project view is original note, not a cloned record',()=>assert.strictEqual(projectContext.projectNote,projectNote));
check('project goal is original linked planning note',()=>assert.deepEqual(projectContext.goals.map(g=>g.noteId),['g']));
check('project area is original source-backed area',()=>assert.equal(projectContext.area.noteId,'a'));
check('project progress is reused verbatim, not recomputed from other notes',()=>assert.equal(projectContext.project.progressPercent,50));
check('linked literature note found through explicit note link',()=>assert.deepEqual(projectContext.linkedNotes.map(n=>n.noteId),['r']));
check('tag-and-folder similarity cannot invent study links',()=>assert(!projectContext.linkedNotes.some(n=>n.noteId==='u')));
check('locked and trashed knowledge never enters linked notes',()=>assert(!projectContext.linkedNotes.some(n=>['s','d'].includes(n.noteId))));
check('project and literature source tasks combine only through verified links',()=>assert.equal(projectContext.tasks.length,3));
check('unrelated task from same tag excluded',()=>assert(!projectContext.tasks.some(t=>t.noteId==='u')));
check('completed source task displayed but never scheduled as pending',()=>assert.equal(projectContext.upcoming.filter(x=>x.kind==='task-deadline').length,2));
check('timeline retains task source note ID and exact line',()=>assert(projectContext.upcoming.some(x=>x.noteId==='r'&&x.line===1)));
check('original note reminder appears with distinct type, not a calendar event',()=>assert(projectContext.upcoming.some(x=>x.kind==='note-reminder'&&x.noteId==='p')));
check('project due date appears independently of note reminders',()=>assert(projectContext.upcoming.some(x=>x.kind==='project-deadline'&&x.day==='2026-10-22')));
check('timeline sorts local calendar days, not task insertion order',()=>assert.deepEqual(projectContext.upcoming.map(t=>t.day).slice(0,3),['2026-10-18','2026-10-19','2026-10-20']));
check('project without planning record returns null instead of fake dashboard',()=>assert.equal(buildProjectContext('r',index,projects,goals,areas,[],graph),null));
check('project with missing original note returns no dashboard',()=>assert.equal(buildProjectContext('p',buildKeepDiscoveryIndex([materialNote],projects,goals,areas),projects,goals,areas,[],graph),null));
check('source-related external URI is not treated as a local study note',()=>{const p=make({},[{id:'x',fromUri:makeOwnerRef('keep','project','p').uri,toUri:makeOwnerRef('vault','note','other').uri,label:'reference',createdAt:'2026-10-16T00:00:00Z'}]);assert.equal(p.linkedNotes.length,1)});
check('overdue project is accurately distinguished',()=>assert.equal(make({due:'2026-10-15'}).status,'overdue'));
check('due-soon project is accurately distinguished',()=>assert.equal(make({due:'2026-10-19'}).status,'due-soon'));
check('unplanned project has honest missing next action',()=>assert.equal(make({due:undefined,nextActionTask:null}).status,'unplanned'));
check('blocked project does not show on-track',()=>assert.equal(make({blockedByIds:['r']}).status,'blocked'));
check('waiting project does not imply completion',()=>assert.equal(make({status:'waiting',due:undefined}).status,'waiting'));
check('same-origin explicit note link is enough without Wikilink guess',()=>{const extra=note('e',{title:'Essay',content:'Essay'});const extended=buildKeepDiscoveryIndex([...notes,extra],projects,goals,areas);const p=buildProjectContext('p',extended,projects,goals,areas,[{id:'link',fromUri:makeOwnerRef('keep','note','p').uri,toUri:makeOwnerRef('keep','note','e').uri,label:'reading',createdAt:'2026-10-16T00:00:00Z'}],undefined,'2026-10-16');assert(p.linkedNotes.some(n=>n.noteId==='e'))});
const sourceTask=[...index.taskById.values()].find(t=>t.noteId==='p'&&!t.completed);
check('rescheduling preserves original note ID and task ^block anchor',()=>{const edited=prepareKeepTaskReschedule(projectNote,sourceTask,'2026-10-21');assert.equal(edited.id,'p');assert(edited.content.includes('@due(2026-10-21) ^slides'));assert(projectNote.content.includes('@due(2026-10-20)'))});
check('safe reschedule refuses invalid calendar date',()=>assert.throws(()=>prepareKeepTaskReschedule(projectNote,sourceTask,'2026-02-30')));
check('safe reschedule rejects stale task line',()=>assert.throws(()=>prepareKeepTaskReschedule({...projectNote,content:projectNote.content.replace('Prepare presentation','Different task')},sourceTask,'2026-10-21')));
check('safe reschedule rejects duplicate source block anchor',()=>assert.throws(()=>prepareKeepTaskReschedule({...projectNote,content:projectNote.content+'\n- [ ] Another ^slides'},sourceTask,'2026-10-21')));
check('safe reschedule rejects changing a completed task',()=>{const task=[...index.taskById.values()].find(t=>t.noteId==='p'&&t.completed);assert.throws(()=>prepareKeepTaskReschedule(projectNote,task,'2026-10-21'))});
check('safe reschedule rejects locked/archived/trash source lifecycle',()=>{for(const field of ['archived','trashed','isLocked'])assert.throws(()=>prepareKeepTaskReschedule({...projectNote,[field]:true},sourceTask,'2026-10-21'))});
check('unanchored task gains due token without invented task identity',()=>{const raw=note('non',{content:'- [ ] Outline lecture'});const task=[...buildKeepDiscoveryIndex([raw],[],[],[]).taskById.values()][0];const changed=prepareKeepTaskReschedule(raw,task,'2026-10-24');assert.equal(changed.content,'- [ ] Outline lecture @due(2026-10-24)')});
check('note frontmatter is left intact when source task inherits a date',()=>{const raw=note('inherit',{content:'---\ndue: 2026-10-20\n---\n- [ ] Submit reading ^read'});const task=[...buildKeepDiscoveryIndex([raw],[],[],[]).taskById.values()][0];const changed=prepareKeepTaskReschedule(raw,task,'2026-10-25');assert(changed.content.includes('due: 2026-10-20'));assert(changed.content.includes('Submit reading @due(2026-10-25) ^read'))});
check('ambiguous duplicated due annotations cannot be changed automatically',()=>{const raw=note('double',{content:'- [ ] Submit @due(2026-10-18) due:2026-10-20 ^same'});const task=[...buildKeepDiscoveryIndex([raw],[],[],[]).taskById.values()][0];assert.throws(()=>prepareKeepTaskReschedule(raw,task,'2026-10-25'))});

const days=buildKeepPlanningDays(index,'2026-10-16',14);
check('planning projection returns exact 14 source days',()=>assert.equal(days.length,14));
check('pending due tasks show in correct day',()=>assert(days.find(d=>d.day==='2026-10-18').tasks.some(t=>t.noteId==='r')));
check('completed tasks never populate pending timeline',()=>assert(!days.some(d=>d.tasks.some(t=>t.completed))));
check('unrelated KEEP tasks remain in global preview',()=>assert(days.find(d=>d.day==='2026-10-19').tasks.some(t=>t.noteId==='u')));
check('project deadlines appear as deadlines, not fabricated events',()=>assert(days.find(d=>d.day==='2026-10-22').projects.some(p=>p.noteId==='p')));
check('note reminder included once from original note',()=>assert.deepEqual(days.find(d=>d.day==='2026-10-19').reminders.map(x=>x.noteId),['p']));
check('invalid dates and huge view requests are safely rejected',()=>{assert.deepEqual(buildKeepPlanningDays(index,'invalid',14),[]);assert.deepEqual(buildKeepPlanningDays(index,'2026-10-16',100),[])});
check('absolute reminder instant renders to locally appropriate day',()=>{const before=reminderLocalDate('2026-10-16T00:30:00Z');assert(/^\d{4}-\d{2}-\d{2}$/.test(before));assert.equal(reminderLocalDate('nonsense'),null)});
check('cross-domain view evaluates all actual rows without duplicating sources',()=>{const v={id:'sv-custom-local',name:'University',domain:'keep-workspace',filters:[{field:'tags',operator:'contains',value:'university'}],createdAt:'2026-10-01',updatedAt:'2026-10-01'};const rows=queryExistingSavedView(index.rows,v);assert(rows.some(r=>r.kind==='task')&&rows.some(r=>r.kind==='note')&&rows.some(r=>r.kind==='project'));assert(!rows.some(r=>r.noteId==='s'))});
check('external Library saved views still do not receive synthetic records',()=>assert.equal(queryExistingSavedView(index.rows,{domain:'library',filters:[]}),null));
(async()=>{
 const view=await savedViewsManager.saveView({name:'KEEP University workspace',domain:'keep-workspace',filters:[{field:'tags',operator:'contains',value:'university'}],sort:{field:'dueDate',direction:'asc'}});
 check('cross-domain view saved through original personalization manager',()=>assert.equal(savedViewsManager.getSavedViewById(view.id).domain,'keep-workspace'));
 check('saved cross-domain query returns notes and tasks on reload',()=>assert(queryExistingSavedView(index.rows,savedViewsManager.getSavedViewById(view.id)).some(r=>r.kind==='task')));
 const bundle=configExportImportManager.generateBundle();
 check('portable custom cross-domain view exported unchanged',()=>assert(bundle.savedViews.some(v=>v.id===view.id&&v.domain==='keep-workspace')));
 await savedViewsManager.deleteView(view.id);
 check('deleted saved view does not survive by title',()=>assert.equal(savedViewsManager.getSavedViewById(view.id),undefined));
 const success=await savedViewsManager.importView(view);
 check('saved view imports with original ID and union domain',()=>{assert.equal(success,'imported');assert.equal(savedViewsManager.getSavedViewById(view.id).id,view.id)});
 check('import cannot duplicate existing view identity',()=>assert.equal(savedViewsManager.getSavedViews().filter(v=>v.id===view.id).length,1));
 await savedViewsManager.deleteView(view.id);
 console.log(`KEEP_B3_MODEL_PASS=${total}`);
})().catch(e=>{console.error(e);process.exitCode=1});
